begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('program_a')::uuid),(md5('program_b')::uuid);
insert into profiles(id,display_name) values(md5('program_a')::uuid,'A'),(md5('program_b')::uuid,'B');
create function pg_temp.rotation(n integer) returns uuid language plpgsql security invoker as $$
declare root uuid; day uuid;
begin
 insert into public.programs(owner_id,name,cycle_length,objective,visibility) values(auth.uid(),'Rotation '||n,n,'hypertrophy','public') returning id into root;
 for i in 1..n loop insert into public.program_days(owner_id,program_id,cycle_length,cycle_position,name,is_rest_day,minimum_rest_hours,maximum_rest_hours) values(auth.uid(),root,n,i,'Day '||i,i=n,24,72) returning id into day;
 if i<>n then insert into public.program_slots(owner_id,program_day_id,position,movement_pattern_id,exercise_id,target_sets,target_reps_min,target_reps_max,required_exercise_type,primary_muscle_id) values(auth.uid(),day,1,(select id from public.movement_patterns where slug='horizontal_push'),(select id from public.exercises where slug='barbell_bench_press'),2,8,12,'compound',(select id from public.muscle_groups where slug='pectorals'));end if;end loop;return root;
end $$;
