select ok(not has_table_privilege('service_role','public.program_reports','DELETE'),'program_reports: service_role DELETE denied');
select ok((select relrowsecurity from pg_class where oid='public.program_admin_events'::regclass),'program_admin_events: RLS enabled');
select ok(not has_any_column_privilege('anon','public.program_admin_events','SELECT'),'program_admin_events: anon SELECT denied');
select ok(not has_any_column_privilege('anon','public.program_admin_events','INSERT'),'program_admin_events: anon INSERT denied');
