select ok(not has_table_privilege('service_role','public.program_admin_events','DELETE'),'program_admin_events: service_role DELETE denied');
select ok(not has_function_privilege('anon','public.clone_program(uuid,text,uuid)','execute'),'anonymous cloning denied');
select ok(not has_function_privilege('service_role','public.snapshot_program(uuid)','execute'),'no service shortcut');
select ok((select bool_and(not prosecdef) from pg_proc where proname in('clone_program','snapshot_program','program_definition','program_slot_eligible')),'program API is invoker');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('program_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.p3',pg_temp.rotation(3)::text,true);
select set_config('body_test.p5',pg_temp.rotation(5)::text,true);
select set_config('body_test.p8',pg_temp.rotation(8)::text,true);
select set_config('body_test.p10',pg_temp.rotation(10)::text,true);
select is((select count(*)::int from program_days where program_id=current_setting('body_test.p8')::uuid),8,'eight-day rotation does not force seven days');
select is((select cycle_position::int from program_days where program_id=current_setting('body_test.p10')::uuid and is_rest_day),10,'ordered rest day at ten-day cycle end');
select is((select minimum_rest_hours from program_days where program_id=current_setting('body_test.p3')::uuid limit 1),24::numeric,'flexible rest guidance independent of calendar scheduling');
select is((select publisher_id from programs where id=current_setting('body_test.p3')::uuid),auth.uid(),'publisher defaults to verified owner');
select ok((select origin='user_created' and publication_status='unpublished' and not recommendation_eligible and moderation_status='unreviewed' from programs where id=current_setting('body_test.p3')::uuid),'stored public visibility does not publish or recommend');
select throws_ok($$update programs set origin='body_authored' where id=current_setting('body_test.p3')::uuid$$,'42501',null,'cannot impersonate Body origin');
select throws_ok($$update programs set publisher_id=md5('program_b')::uuid where id=current_setting('body_test.p3')::uuid$$,'42501',null,'cannot impersonate another publisher');
select throws_ok($$update programs set moderation_status='approved',recommendation_eligible=true where id=current_setting('body_test.p3')::uuid$$,'42501',null,'cannot self-approve moderation/recommendation');
select set_config('body_test.day',(select id::text from program_days where program_id=current_setting('body_test.p3')::uuid and cycle_position=1),true);
select set_config('body_test.slot',(select id::text from program_slots where program_day_id=current_setting('body_test.day')::uuid),true);
insert into program_slot_alternatives(slot_id,owner_id,exercise_id,position) select current_setting('body_test.slot')::uuid,auth.uid(),id,1 from exercises where slug='dumbbell_bench_press';
select ok(program_slot_eligible(current_setting('body_test.slot')::uuid,(select id from exercises where slug='dumbbell_bench_press')),'eligible alternative reuses taxonomy');
select throws_ok($$insert into program_slot_alternatives(slot_id,owner_id,exercise_id,position) select current_setting('body_test.slot')::uuid,auth.uid(),id,2 from exercises where slug='dumbbell_lateral_raise'$$,'23514',null,'incompatible movement/type alternative denied');
insert into program_set_prescriptions(slot_id,owner_id,position,set_type,reps_min,reps_max,effort_scale,effort_value,intended_to_failure) values(current_setting('body_test.slot')::uuid,auth.uid(),1,'working',8,12,'rir',2,false),(current_setting('body_test.slot')::uuid,auth.uid(),2,'working',8,12,null,null,true);
select is((select count(*)::int from program_set_prescriptions where slot_id=current_setting('body_test.slot')::uuid),2,'explicit ordered planned sets retained');
select throws_ok($$update program_set_prescriptions set effort_scale='rpe',effort_value=5 where slot_id=current_setting('body_test.slot')::uuid$$,'23514',null,'invalid prescribed effort denied');
select throws_ok($$update program_set_prescriptions set reps_min=12,reps_max=8 where slot_id=current_setting('body_test.slot')::uuid$$,'23514',null,'invalid rep range denied');
select throws_ok($$insert into program_slots(owner_id,program_day_id,position,movement_pattern_id,target_sets) select auth.uid(),id,1,(select id from movement_patterns where slug='horizontal_push'),1 from program_days where program_id=current_setting('body_test.p3')::uuid and is_rest_day$$,'23514',null,'rest day cannot contain a slot');
insert into program_progression_rules(id,program_id,owner_id,name,strategy,load_step_kg,rep_step,reps_min,reps_max) values(md5('p_rule')::uuid,current_setting('body_test.p3')::uuid,auth.uid(),'Double','double_progression',2.5,1,8,12);
update program_slots set progression_rule_id=md5('p_rule')::uuid where id=current_setting('body_test.slot')::uuid;
select throws_ok($$insert into program_progression_rules(program_id,owner_id,name,strategy,load_step_kg) values(current_setting('body_test.p3')::uuid,auth.uid(),'Bad','linear_load',-1)$$,'23514',null,'invalid typed progression configuration denied');
select throws_ok($$update program_slots set progression_rule_id=md5('p_rule')::uuid where program_day_id in(select id from program_days where program_id=current_setting('body_test.p5')::uuid)$$,'23514',null,'same-owner rule from a different program denied');
select set_config('body_test.v1',snapshot_program(current_setting('body_test.p3')::uuid)::text,true);
select set_config('body_test.v8',snapshot_program(current_setting('body_test.p8')::uuid)::text,true);
select is((select version from program_versions where id=current_setting('body_test.v1')::uuid),1,'server assigns immutable version number');
select throws_ok($$update program_versions set definition='{}' where id=current_setting('body_test.v1')::uuid$$,'42501',null,'clients cannot rewrite immutable version');
select throws_ok($$insert into program_versions(program_id,owner_id,definition,version) values(current_setting('body_test.p3')::uuid,auth.uid(),'{}',999)$$,'42501',null,'clients cannot forge snapshot JSON or version');
select set_config('body_test.copy',clone_program(current_setting('body_test.v1')::uuid,'My independent copy',md5('copy_request')::uuid)::text,true);
select is(clone_program(current_setting('body_test.v1')::uuid,'Retry',md5('copy_request')::uuid),current_setting('body_test.copy')::uuid,'same clone request is idempotent');
select isnt(current_setting('body_test.copy')::uuid,current_setting('body_test.p3')::uuid,'copy has independent identity');
select ok((select owner_id=auth.uid() and publisher_id=auth.uid() and origin='user_copy' and visibility='private' and publication_status='unpublished' and not recommendation_eligible and source_version_id=current_setting('body_test.v1')::uuid from programs where id=current_setting('body_test.copy')::uuid),'clone owns its recipe and resets publication permissions');
select is((select count(*)::int from program_days where program_id=current_setting('body_test.copy')::uuid),3,'full rotation copied');
select is((select count(*)::int from program_set_prescriptions x join program_slots s on s.id=x.slot_id join program_days d on d.id=s.program_day_id where d.program_id=current_setting('body_test.copy')::uuid),2,'planned effort/failure prescriptions copied independently');
update programs set name='Updated source' where id=current_setting('body_test.p3')::uuid;
update program_slots set target_reps_min=9 where id=current_setting('body_test.slot')::uuid;
select is((select definition->'program'->>'name' from program_versions where id=current_setting('body_test.v1')::uuid),'Rotation 3','source version does not change with source draft');
select is((select name from programs where id=current_setting('body_test.copy')::uuid),'My independent copy','copy does not change with source');
select is((select target_reps_min from program_slots s join program_days d on d.id=s.program_day_id where d.program_id=current_setting('body_test.copy')::uuid and d.cycle_position=1),8,'copy prescriptions isolated from source edits');
select set_config('body_test.v2',snapshot_program(current_setting('body_test.p3')::uuid)::text,true);
select is((select version from program_versions where id=current_setting('body_test.v2')::uuid),2,'new draft snapshot gets next version');
select is((select count(*)::int from workout_sessions where owner_id=auth.uid()),0,'program definitions never create actual sessions or effort');
select set_config('request.jwt.claims',json_build_object('sub',md5('program_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from programs),0,'public-valued private programs not discoverable to other users');
select is((select count(*)::int from program_days),0,'foreign rotation children hidden');
select is((select count(*)::int from program_set_prescriptions),0,'foreign planned effort hidden');
select is((select count(*)::int from program_versions),0,'foreign source snapshots hidden');
select throws_ok($$select clone_program(current_setting('body_test.v1')::uuid,'Stolen',gen_random_uuid())$$,'42501',null,'cross-owner clone denied before community gate exists');
select throws_ok($$select snapshot_program(current_setting('body_test.p3')::uuid)$$,'42501',null,'cannot snapshot another owner program');
select throws_ok($$insert into creator_accounts(profile_id,identity_status) values(auth.uid(),'verified')$$,'42501',null,'no self-issued verified status');
select throws_ok($$insert into program_reports(program_identity,category,explanation) values(current_setting('body_test.p3')::uuid,'copyright','Claim')$$,'42501',null,'public complaint endpoints remain disabled');
select set_config('request.jwt.claims',json_build_object('sub',md5('program_a')::uuid,'role','authenticated')::text,true);
select throws_ok($$delete from programs where id=current_setting('body_test.p3')::uuid$$,'42501',null,'ordinary destructive root deletion denied');
with made as(insert into workout_sessions(owner_id,name,source_program_id,program_name_snapshot) values(auth.uid(),'Recorded copy workout',current_setting('body_test.copy')::uuid,'My independent copy') returning id) select set_config('body_test.copy_history',id::text,true) from made;
select set_config('body_test.copy_history_item',edit_workout(current_setting('body_test.copy_history')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select lives_ok($$select log_workout_set(current_setting('body_test.copy_history_item')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.copy_history_item')::uuid order by position limit 1),'save',0,gen_random_uuid(),5,50,'working','external',true)$$,'record actual performance independently of recipe');
select end_workout(current_setting('body_test.copy_history')::uuid,'completed');
reset role;
-- Simulate future authorized execution snapshot linkage locally, not an app activation flow.
update workout_sessions set source_program_version_id=current_setting('body_test.v1')::uuid,program_version_snapshot=1 where id=current_setting('body_test.copy_history')::uuid;
set local role authenticated;
reset role;
delete from programs where id=current_setting('body_test.p3')::uuid;
set local role authenticated;
select ok((select program_id is null and definition->'program'->>'name'='Rotation 3' from program_versions where id=current_setting('body_test.v1')::uuid),'privileged source deletion keeps immutable recipe snapshot');
select ok((select source_version_id=current_setting('body_test.v1')::uuid and source_attribution->>'name'='Rotation 3' from programs where id=current_setting('body_test.copy')::uuid),'copy source attribution survives source deletion');
select is((select count(*)::int from program_days where program_id=current_setting('body_test.copy')::uuid),3,'source deletion never cascades into independent copy');
select ok((select status='completed' and program_name_snapshot='My independent copy' from workout_sessions where id=current_setting('body_test.copy_history')::uuid),'source deletion preserves completed workout snapshot');
select is((select actual_weight_kg from workout_sets where workout_exercise_id=current_setting('body_test.copy_history_item')::uuid and status='completed'),50::numeric,'source deletion never removes actual performance');
select * from finish();rollback;
